# -*- coding: utf-8 -*-
import json, os, re

ROOT = r'D:\repository'
sel = json.load(open(r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json', encoding='utf-8'))
cands = sel['candidates']

# Build basename index of source files (skip heavy dirs)
SKIP = {'node_modules','dist','.git','build','.nuxt','coverage','vendor','target','__pycache__'}
INDEX = {}
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [d for d in dns if d not in SKIP]
    for fn in fns:
        if re.search(r'\.(vue|js|ts|jsx|tsx|scss|css|json|md|py|java|xml|wxml|wxss)$', fn, re.I):
            INDEX.setdefault(fn.lower(), []).append(os.path.join(dp, fn))

EXT = r'(?:vue|js|ts|jsx|tsx|scss|css|json|py|java|xml|wxml|wxss)'
# filenames mentioned explicitly (with or without path)
fname_re = re.compile(r'([A-Za-z0-9_\-\u4e00-\u9fff]+\.'+EXT+r')\b')

def keytokens(content):
    # backtick-quoted identifiers (skip URLs, long prose)
    toks = re.findall(r'`([^`\n]{2,60})`', content)
    keys = []
    seen = set()
    for t in toks:
        t = t.strip()
        # keep code-like tokens
        if re.search(r'[A-Za-z_$][A-Za-z0-9_$]*', t) and ' ' not in t and len(t) < 50:
            if t not in seen:
                seen.add(t); keys.append(t)
    return keys[:24]

report = []
for i, c in enumerate(cands, 1):
    content = c['content']
    names = fname_re.findall(content)
    names = list(dict.fromkeys([n for n in names]))
    matched = {}
    for n in names:
        paths = INDEX.get(n.lower(), [])
        if paths:
            matched[n] = paths[:4]
    missing = [n for n in names if n not in matched]
    report.append({
        'i': i, 'sha': c['body_sha256_16'],
        'uri': c['uri'].split('/memories/')[-1],
        'names': names,
        'matched': matched,
        'missing': missing,
        'keys': keytokens(content),
    })

out = []
for r in report:
    out.append('===== [%d] %s %s' % (r['i'], r['sha'], r['uri']))
    out.append('FILES:')
    for n, ps in r['matched'].items():
        out.append('  + %s -> %s' % (n, ' | '.join(p.replace(ROOT+'\\','') for p in ps)))
    for n in r['missing']:
        out.append('  - %s (NOT FOUND)' % n)
    out.append('KEYS: ' + ', '.join(r['keys']))
    out.append('')
open(r'C:/Users/Administrator/.dsh/cache/memory-audit/_evidence.txt','w',encoding='utf-8').write('\n'.join(out))
print('index size', len(INDEX))
print('report lines', len(out))

